// Alert only when something was recovered, or when the set of offline workers or of
// provider-blocked videos changes (avoids a message every minute for a lasting state).
const raw = $input.first().json.summary;
const summary = typeof raw === 'string' ? JSON.parse(raw) : raw;
const state = $getWorkflowStaticData('global');
const offline = (summary.offline_workers || []).join(',');
const offlineChanged = offline !== (state.lastOffline || '');
state.lastOffline = offline;
const blocked = (summary.blocked_videos || []).map((id) => String(id).slice(0, 8)).sort().join(',');
const blockedChanged = blocked !== (state.lastBlocked || '');
state.lastBlocked = blocked;
const decisions = (summary.needs_decision || []).map(
  (v) => `Video ${String(v.video_id).slice(0, 8)} v${v.version} needs a decision: ${v.step ?? 'step'} failed: ${v.error ?? 'unknown error'}`,
);
const newDecisions = decisions.filter((line) => !(state.lastDecisions || []).includes(line));
state.lastDecisions = decisions;

const lines = [];
if (summary.expired_leases > 0) lines.push(`Expired leases recovered: ${summary.expired_leases}`);
if (summary.requeued > 0) lines.push(`Lost queue messages re-queued: ${summary.requeued}`);
if (summary.approvals_expired > 0) lines.push(`Approvals expired: ${summary.approvals_expired}`);
if (offlineChanged) lines.push(offline ? `Workers offline: ${offline}` : 'All workers back online');
if (blockedChanged) lines.push(blocked ? `Videos blocked by a provider limit (waiting, no fallback): ${blocked}` : 'No videos blocked by a provider');
lines.push(...newDecisions);

if (lines.length === 0) return [];
return [{ json: { text: ['[AI Video] Watchdog', ...lines].join('\n') } }];
